# (1.316.0) Les autres pièces jouées (un négoce de matériaux de Sousse et sa comptable) : la facture des bons de livraison ne
# ressort pas ce que les bons ont sorti, ligne par ligne (`fromBon`) — une ligne ajoutée sur elle sort le stock, sa copie
# est une autre vente ; plus de fausse alerte « il en manque ». Et deux fiches identiques dont seul l'ordre des champs
# diffère ne sont pas « modifiées des deux côtés ».
APP1=modules/socle/ecrans/entreprise/app-1.js
CORE1=modules/socle/moteur/core-1.js
CORE2=modules/socle/moteur/core-2.js
T316="le négoce livre une commande en deux bons, facture les bons avec un sac de plâtre en plus, fait une proforma et un contrat, et le comptable lit la vente"
TB316a="« Facturer ce bon » : ses lignes disent leur bon et ne ressortent pas ; dix sacs ajoutés sortent ; sa copie est une autre vente"
TB316b="une facture d'avant 1.316 tirée d'un bon, sans marque sur ses lignes, reste entière au bon"
TB316c="deux fiches identiques, champs dans un autre ordre (le serveur rend le sien) : aucune « modifiée des deux côtés »"
prouver 'deux fiches dans un autre ordre se disent en conflit' "$CORE2" \
  "JSON.stringify(a) === JSON.stringify(b) || JSON.stringify(enOrdre(a)) === JSON.stringify(enOrdre(b));" "JSON.stringify(a) === JSON.stringify(b);" \
  "$TB316c"
prouver 'la facture des bons ne dit pas de quel bon vient sa ligne' "$CORE2" \
  "      l.fromBon = b.number || '';" "" \
  "$T316"
prouver 'une ligne livrée en deux bons ne nomme que le premier' "$CORE2" \
  "if (b.number && !String(deja.fromBon || '').split(', ').includes(b.number)) deja.fromBon = [deja.fromBon, b.number].filter(Boolean).join(', '); return; }" "return; }" \
  "$T316"
prouver 'facturer un seul bon ne marque pas ses lignes' "$CORE2" \
  "out.lines = (out.lines || []).map(l => (l && !l.noDiscount ? { ...l, fromBon: doc.number || '' } : l));" "out.lines = out.lines || [];" \
  "$TB316a"
prouver 'un avoir garde la marque du bon' "$CORE2" \
  "    else (out.lines || []).forEach(l => { if (l) delete l.fromBon; });" "" \
  "$TB316a"
prouver 'la ligne ajoutée sur la facture des bons ne sort pas le stock' "$CORE1" \
  "        if (isSale && sortieAuBon(d, l)) return;" "        if (isSale && d.fromDocType === 'livraison') return;" \
  "$T316"
prouver 'une ligne marquée de son bon ressort le stock' "$CORE1" \
  "    if (l.fromBon) return true;" "" \
  "$TB316a"
prouver 'une facture d'\''avant 1.316 ressort le stock de son bon' "$CORE1" \
  "    return d.fromDocType === 'livraison' && !(d.lines || []).some(x => x && x.fromBon);" "    return false;" \
  "$TB316b"
prouver 'l'\''émission de la facture des bons crie au stock insuffisant' "$CORE1" \
  "lignesDeStock((doc.lines || []).filter(l => !sortieAuBon(doc, l)), data)" "lignesDeStock(doc.lines || [], data)" \
  "$T316"
prouver 'la copie de la facture des bons garde la marque des bons' "$APP1" \
  "    (copy.lines || []).forEach(l => { if (l) delete l.fromBon; });   // (1.316.0) une copie est une autre vente : elle sort le stock" "" \
  "$T316"
prouver 'un transport livré avec le bon se dit sorti du stock' "$APP1" \
  "\${it && it.tracked ? \`\${h(l.fromBon)} · déjà sorti du stock\` : \`livré avec \${h(l.fromBon)}\`}" "\${h(l.fromBon)} · déjà sorti du stock" \
  "$T316"

# (1.317.0) Les listes de prix jouées (une droguerie de l'Ariana, ses artisans, son hôtel, son comptoir, puis sa comptable) :
# la caisse prend le prix d'une facture au même client (sa liste, le palier de la quantité) et le dit ; le choix d'un
# article dit le prix que sa ligne prendra ; changer de client reprend les prix du catalogue posés ; la fiche du client dit
# la liste qui fait ses prix (la règle du moteur) ; la facture d'un devis plus cher que la liste le dit, et « Reprendre
# ses prix » les pose ; le client d'une liste ne paie jamais plus qu'un passant au-delà d'un palier.
APP1=modules/socle/ecrans/entreprise/app-1.js
APP2=modules/socle/ecrans/entreprise/app-2.js
CORE1=modules/socle/moteur/core-1.js
CORE2=modules/socle/moteur/core-2.js
T317="la droguerie vend à ses artisans, à son hôtel et au comptoir, chacun à son prix, et le comptable lit les ventes"
TP317a="le client d'une liste ne paie jamais plus qu'un passant : au-delà d'un palier plus bas que sa liste, c'est le palier"
TP317b="le panier de la caisse prend le prix d'une facture au même client, et le reprend quand le client change"
prouver 'le client d'\''une liste paie plus qu'\''un passant au-delà du palier' "$CORE1" \
  "      if (palier !== (Number(item && item.unitPrice) || 0) && palier < Number(x.prix)) return { prix: palier, source: 'palier', liste: '' };" "" \
  "$TP317a"
prouver 'le panier de la caisse garde le prix du catalogue' "$CORE2" \
  "l.unitPrice = p.prix; l.prixSource" "l.prixSource" \
  "$TP317b"
prouver 'la caisse ne reprend pas les prix du client' "$APP2" \
  "        C.prixDuPanier(data, s.panier, s.clientId, C.today());" "" \
  "$T317"
prouver 'la tuile de la caisse dit le prix du catalogue' "$APP2" \
  "lines: C.prixDuPanier(data, [C.ligneDePanier(it, company())], s.clientId, C.today()) }" "lines: [C.ligneDePanier(it, company())] }" \
  "$T317"
prouver 'la ligne du ticket ne dit pas d'\''où vient son prix' "$APP2" \
  "l'unité\${l.prixSource === 'liste'" "l'unité\${false" \
  "$T317"
prouver 'choisir le client à la caisse ne redessine pas les tuiles' "$APP2" \
  "close(); drawTicket(); drawArticles(); };" "close(); drawTicket(); };" \
  "$T317"
prouver 'le choix d'\''un article dit le prix du catalogue' "$APP1" \
  "const prixAffiche = c => enDevise(prixDuChoix(c));" "const prixAffiche = c => enDevise(c.unitPrice);" \
  "$T317"
prouver 'le choix d'\''un article tait son palier' "$APP1" \
  "'prestation', palierDuChoix(c), v ?" "'prestation', v ?" \
  "$T317"
prouver 'changer de client garde les prix de l'\''ancien' "$APP1" \
  "          l.unitPrice = apres; delete l.puTtc; reprises++;" "" \
  "$T317"
prouver 'changer de client reprend les prix sans le dire' "$APP1" \
  "        if (reprises) toast(" "        if (false) toast(" \
  "$T317"
prouver 'la fiche du client cherche sa liste sans la règle du moteur' "$APP1" \
  "const listeC = C.listesPrixApplicables(data, c.id, tPrix)[0] || null;" "const listeC = (data.priceLists || []).find(l => String(l.categorie || '').trim() === String(c.categorieTarif || '').trim()) || null;" \
  "$T317"
prouver 'la facture d'\''un devis tait la liste moins chère' "$APP1" \
  "          if (x) points.push([false, \`\${prixAReprendre.length > 1" "          if (false) points.push([false, \`\${prixAReprendre.length > 1" \
  "$T317"
prouver 'reprendre ses prix ne pose rien' "$APP1" \
  "        prixAReprendre.forEach(({ l, pu }) => { l.unitPrice = pu; delete l.puTtc; });" "" \
  "$T317"

# (1.317.1) Le rouge de 1.314.0 : une restauration à une minute que les journaux archivés n'atteignent pas arrête
# PostgreSQL, et l'attente durait l'heure entière sur une base arrêtée. Elle se voit, se dit (la dernière écriture
# archivée), et « --jusqua dernier » restaure tout ce qui est archivé, gardé à part.
RESTAURER=exploitation/restaurer.sh
TR1="une minute que les journaux archivés n'atteignent pas se refuse tout de suite, et dit comment tout reprendre"
TR2="« --jusqua dernier » : tout ce qui est archivé revient, et reste à part"
prouver 'la restauration attend une base arrêtée' "$RESTAURER" \
  '  "$PGBIN/pg_ctl" -D "$DONNEES" status >/dev/null 2>&1 || break' "" \
  "$TR1"
prouver 'une minute que les journaux n'\''atteignent pas se dit « échec à la ligne »' "$RESTAURER" \
  "    && grep -q 'recovery ended before configured recovery target was reached'" "    && false && grep -q 'recovery ended before configured recovery target was reached'" \
  "$TR1"
prouver 'la minute refusée tait la dernière écriture archivée' "$RESTAURER" \
  '(heure de Tunis)${ecrite:+ : leur dernière écriture est $ecrite}.' '(heure de Tunis).' \
  "$TR1"
prouver '« --jusqua dernier » se lit comme une date' "$RESTAURER" \
  'if [ "${1:-}" = --jusqua ] && [ "${2:-}" = dernier ]; then' 'if false; then' \
  "$TR2"

